import kotlinx.coroutines.*
import kotlinx.coroutines.flow.*

fun main() = runBlocking {
    var starts = 0
    val upstream = flow {
        starts++
        emit(1); delay(100); emit(2)
    }
    val shared = upstream.shareIn(this, SharingStarted.Eagerly, replay = 1)
    val a = launch { shared.take(2).collect { print("A$it ") } }
    val b = launch { shared.take(2).collect { print("B$it ") } }
    joinAll(a, b)
    println("starts=$starts")
    coroutineContext.cancelChildren()
}
